#include <bits/stdc++.h>
using namespace std; 
typedef long long ll;
int studentcount;

int main(){
    int t; cin>>t;
    while(t--){
        int teamcount; cin>>teamcount;
        studentcount=3*teamcount; int a=1;
        vector<ll>rating(studentcount);
        for (int i=0; i<studentcount; ++i) cin>>rating[i];
        sort(rating.begin(),rating.end(),greater<ll>());
        vector<ll>pre(studentcount+1,0);
        for (int i=0; i<studentcount; ++i) pre[i+1]=pre[i]+rating[i];
        auto edge=[&](int p,int q)-> ll {
            return 2*pre[p]+pre[p+2*q]+3*pre[studentcount-2*p-q];
        };
        ll outt=0;
        for (int p=0; p<=teamcount; ++p){
            int l0=0,high=teamcount-p;
            while(l0<high){
                int mid=l0+(high-l0)/2;
                if (edge(p,mid)<edge(p,mid+1)) l0=mid+1;
                else high=mid;
            }
            outt=max(outt,edge(p,l0));
        }
        if (a)
        cout<<outt<<endl;
    }
}
